        const nextColumn = column + columnChange;
        if (
          isInBounds(image, nextRow, nextColumn) &&
          image[nextRow][nextColumn] === originalColor
        ) {
          image[nextRow][nextColumn] = color;
          stack.push([nextRow, nextColumn]);
        }
