    components++;
    const stack = [node];
    visited.add(node);
    while (stack.length) {
      const currentNode = stack.pop();
      for (const next of graph[currentNode]) {
        if (!visited.has(next)) {
          visited.add(next);
          stack.push(next);
        }
      }
    }
  }
  return components;
}

